  !/[\u0000-\u001f\u007f]/u.test(x)&&
  !/(?:https?:\/\/|www\.|@|(?:\+?\d[\s.-]?){9,}|\b(?:whatsapp|tel[eé]fono|celular|cuit|cuil|correo|email|raz[oó]n social)\b)/iu.test(x);
