 }
 let context:ContextoConversacionV2;
 try{context=await abrirConversacionTextoV2({chatHmac:chat,fuentes:sources,descifrar:io.decrypt,sha256:io.sha,
  leerDocumento:async(f,manifest)=>{
   const scoped=await call('cotironda_piloto_v2_conversation_document_source',{...fields,p_message_hmac:f.message_hmac});
   if(scoped.state!=='authorized_document'||typeof scoped.size!=='number'||!Number.isSafeInteger(scoped.size)||scoped.size<1||scoped.size>3145728||!io.readDocumentBytes)throw Error('attachment_not_ready');
