  // La RPC comprueba proveedor + fuente íntegra + términos y aviso previo.
  // No enviamos confirmaciones ni documentos desde este bloque.
  if(row.type==='text'&&(
    body==='ACEPTO COTIRONDA ORIGINALES V2'||
    /^(?:NO COMPARTIR|No compartir|no compartir)\.?$/u.test(body))){
    if(!['duplicate','unrecognized_contact'].includes(outcome(out.data))){
      const acepta=body==='ACEPTO COTIRONDA ORIGINALES V2';
      const permiso=await db.rpc(acepta?
        'cotironda_piloto_v2_d016_register_terms_acceptance_private':
        'cotironda_piloto_v2_d016_revoke_by_whapi_text_private',{
          p_message_hmac:messageHash,p_chat_hmac:chatHash
        });
      if(permiso.error||
         (acepta&&!['recorded','unchanged','denied'].includes(permiso.data))||
         (!acepta&&(!Number.isSafeInteger(permiso.data)||permiso.data<0)))
        return json(503,'d016_original_permission_reconciliation_required');
    }
    continue;
  }
  if(webLinkCode){
    // A replay cannot create a second link or trigger a false quote.
    if(!['duplicate','unrecognized_contact'].includes(outcome(out.data))){
      const bound=await db.rpc('cotironda_piloto_complete_web_link_mvp126',{
        p_chat_hmac:chatHash,p_message_hmac:messageHash,p_code:webLinkCode
      });
      if(bound.error)return json(503,'web_link_reconciliation_required');
      // Deliberately no WhatsApp echo; the verified web session refreshes
      // the dashboard to observe the linked state. Never log a linking code.
    }
    continue;
  }
  // MVP333: conexión archivada; sin IA, ni aviso de error, ni ronda.
  if(connectivityOnlyMvp333){connectivityCountMvp333++;continue;}
  // Buyer confirmation is NOT a new material request, zone clarification,
  // supplier price or an instruction to the language model.
  if(buyerReviewCommand){
    if(!['duplicate','unrecognized_contact'].includes(outcome(out.data))&&
       allowBuyerConfirmation){
      const decision=await confirmarPedidoCompradorMvp279({
        habilitado:true,
        liberar:sec.outbound&&trialActive&&trial.buyer===true&&
          trial.dispatch===true&&allowBuyerRelease,
        compradorAutenticado:!supplierKnown&&!centralSupplier,
        chatHmac:chatHash,replyHmac:messageHash,textoOriginal:body,
        rpc:async(name,params)=>{
          const r=await db.rpc(name,params);
          return {data:r.data,error:r.error};
        }
      });
      if(decision.estado==='conciliacion_requerida')
        return json(503,'buyer_review_confirmation_reconciliation');
      if(decision.estado==='publicado'){
        trialDispatchChats.add(chatHash);
        buyerLinkRequests.push({mode:'confirmed',requestId:decision.requestId,
         chatHmac:chatHash,eventHmac:messageHash,recipient:row.chat_id});
       }
    }
    continue;
  }
  // Recuperacion solicitada explicitamente para una ronda ya confirmada.
   // Este comando NO crea rondas ni invita nuevamente a proveedores.
   if(buyerLinkCommand){
    if(!['duplicate','unrecognized_contact'].includes(outcome(out.data))&&
       trial.buyer===true&&!supplierKnown&&!centralSupplier&&
       permitirRecuperacionD016(sec.outbound,
        Deno.env.get('COTIRONDA_PILOT_D016_WHATSAPP_SEND_ENABLED')==='true',
        Deno.env.get('COTIRONDA_PILOT_BUYER_TRACKING_ENABLED')))
     buyerLinkRequests.push({mode:'recovery',requestId:null,
      chatHmac:chatHash,eventHmac:messageHash,recipient:row.chat_id});
    continue;
   }

  // Cola conversacional: activación SQL OFF por defecto.
  let groupedBuyerMedia=false;
  if(centralConfigured&&!supplierKnown&&!centralSupplier&&
     (centralBuyerText||['document','image','audio','voice'].includes(row.type))&&
     ['needs_review','needs_zone','duplicate'].includes(outcome(out.data))){
   const flag=await db.rpc('cotironda_piloto_v2_conversation_enabled');
   if(flag.error)return json(503,'conversation_gate_unavailable');
   if(flag.data===true){
    const queued=await db.rpc('cotironda_piloto_v2_conversation_enqueue',{p_chat_hmac:chatHash,p_message_hmac:messageHash});
    if(queued.error)return json(503,'conversation_queue_unavailable');
    if(!['queued','duplicate','source_not_eligible','not_authorized'].includes(queued.data?.state))
     return json(503,'conversation_queue_state_invalid');
    if(row.type==='text'||outcome(out.data)==='duplicate')continue;
    groupedBuyerMedia=true;
   }
  }
  // V2: archivar primero, interpretar intención antes de cualquier asociación
  // comercial. Los controles explícitos de consentimiento/enlace ya salieron.
  if(row.type==='text'&&(centralSupplier||supplierKnown)&&
     !webLinkCode&&!buyerReviewCommand&&!buyerLinkCommand&&
     !respuestaCitaPedidoMvp239(body)&&outcome(out.data)!=='unrecognized_contact'){
    // Separate flag stays OFF until multi-source economic publication is ready.
    const supplierBuffer=await db.rpc('cotironda_piloto_v2_supplier_conversation_enabled');
    if(supplierBuffer.error)return json(503,'supplier_conversation_gate_unavailable');
    if(supplierBuffer.data===true&&trial.quote_link===true&&['needs_review','unmatched_quote','duplicate'].includes(outcome(out.data))&&!attachmentNotice){
     let reference=supplierQuotedId;
     if(!reference&&contieneReferenciaPedidoV2(body)){
      const lookup=await db.rpc('cotironda_piloto_v2_quoted_id_for_reference',{p_message_hmac:messageHash,p_chat_hmac:chatHash,p_original_text:body});
      if(lookup.error)return json(503,'supplier_conversation_reference_unavailable');
      reference=lookup.data?.state==='matched'&&typeof lookup.data.quoted_whapi_id==='string'?lookup.data.quoted_whapi_id:'unmatched-'+messageHash;
     }
     const q=await db.rpc('cotironda_piloto_v2_supplier_conversation_enqueue',{p_chat_hmac:chatHash,p_message_hmac:messageHash,p_reference:reference});
     if(q.error)return json(503,'supplier_conversation_queue_unavailable');
     if(['queued','duplicate'].includes(q.data?.state))continue;
     if(!['source_not_eligible','not_authorized','disabled'].includes(q.data?.state))return json(503,'supplier_conversation_queue_invalid');
    }
    const args={p_message_hmac:messageHash,p_chat_hmac:chatHash,p_source_sha256:textHash};
    const previous=await db.rpc('cotironda_piloto_supplier_text_intent_v2',{...args,p_intent:null});
    if(previous.error)return json(503,'supplier_intent_storage_unavailable');
    let intent=previous.data?.state;
    let receiptState=previous.data?.processing_state;
    if(intent==='classify'){
      const model=Deno.env.get('COTIRONDA_PILOT_AI_CENTRAL_MODEL')==='gpt-6.1-sol'?'gpt-6.1-sol':'gpt-6-luna';
      let questionFields:CampoConsultaProveedorV2[]=[];
      const decision=await interpretarIntencionTextoProveedorV2({
       source:body,apiKey:Deno.env.get('COTIRONDA_PILOT_OPENAI_API_KEY')??'',model,
       hasQuotedRequest:supplierQuotedId!==null,onQuestion:fields=>{questionFields=fields;}
      });
      // Fallo de transporte/esquema: original privado, reintento del webhook.
      // Un fallo de IA nunca se convierte en presupuesto.
      if(decision===null)return json(503,'supplier_intent_retry_required');
      // Los avisos reconocidos por el circuito de adjuntos conservan su enlace
      // contextual; otras variantes quedan privadas hasta que llegue el archivo.
      if((decision==='non_quote'||decision==='quote')&&questionFields.length){
       let quoted=supplierQuotedId;
       if(!quoted&&contieneReferenciaPedidoV2(body)){
        const reference=await db.rpc('cotironda_piloto_v2_quoted_id_for_reference',{p_message_hmac:messageHash,p_chat_hmac:chatHash,p_original_text:body});
        if(reference.error)return json(503,'supplier_question_reference_unavailable');
        quoted=reference.data?.state==='matched'&&typeof reference.data.quoted_whapi_id==='string'
         ?reference.data.quoted_whapi_id:'unmatched-reference';
       }
       const question=await db.rpc('cotironda_piloto_v2_supplier_question',{...args,p_quoted_whapi_id:quoted,p_fields:questionFields,p_intent:decision});
       if(question.error)return json(503,'supplier_question_unavailable');
       if(question.data?.state==='reply_reserved'){
        const reply=responderConsultaProveedorV2(question.data);
        let status:'api_accepted'|'uncertain'='uncertain';
        try{
         if(reply&&sec.outbound&&/^[1-9][0-9]{7,16}@s[.]whatsapp[.]net$/u.test(row.chat_id)&&
          equalSecret(await hmac(sec.key,'cotironda|pilot|chat|'+sec.channel+'|'+row.chat_id),chatHash)){
          const sent=await fetch('https://gate.whapi.cloud/messages/text',{method:'POST',headers:{Authorization:'Bearer '+sec.token,'Content-Type':'application/json'},body:JSON.stringify({to:row.chat_id,body:reply}),signal:AbortSignal.timeout(12000)});
          const response=sent.ok?await sent.json().catch(()=>null):null;
          if(sent.ok&&response?.sent===true)status='api_accepted';
         }
        }catch{/* no retry on uncertain delivery */}
        const finished=await db.rpc('cotironda_piloto_finish_reply_mvp094',{p_message_hmac:messageHash,p_state:status});
        if(finished.error||finished.data!==true)return json(503,'supplier_question_delivery_reconciliation');
       }else if(!['recorded','already_processed','denied'].includes(question.data?.state))return json(503,'supplier_question_state_invalid');
        // Una consulta no debe consumir una oferta mixta. Reutiliza la clasificación persistida.
        if(decision==='non_quote')continue;
      }
      const normalized=decision==='attachment_notice'&&!attachmentNotice?'non_quote':decision;
      const saved=await db.rpc('cotironda_piloto_supplier_text_intent_v2',{...args,p_intent:normalized});
      if(saved.error)return json(503,'supplier_intent_storage_unavailable');
      intent=saved.data?.state;receiptState=saved.data?.processing_state;
    }
    if(['non_quote','uncertain','already_processed','denied'].includes(intent))continue;
    if(!['quote','attachment_notice'].includes(intent)||
       !['needs_review','unmatched_quote'].includes(receiptState))
      return json(503,'supplier_intent_state_invalid');
    attachmentNotice=intent==='attachment_notice';
    // Permite recuperar una recepción cifrada ya guardada tras fallo transitorio.
    if(outcome(out.data)==='duplicate')out.data={state:receiptState};
  }
   // La reserva SQL verifica identidad de comprador y cuota ANTES de
  // gastar tokens. El mensaje ya fue almacenado cifrado y con SHA original.
  // Un mensaje breve que aporta la localidad continúa el único pedido
  // IA Central previo, sin interpretar "La Plata" como otro presupuesto.
  // La RPC revalida autor, SHA, ventana de tiempo, trial y gates.
  if(centralBuyerText&&outcome(out.data)==='needs_review'){
    // Ciudad normalizada únicamente; atribución de contexto y permisos en SQL.
    const city=ciudadDeRespuestaCentralMvp234(body);
    if(city){
      const claimed=await db.rpc('cotironda_piloto_ia_claim_zone_mvp233',{
        p_chat_hmac:chatHash,p_reply_hmac:messageHash,
        p_reply_text:body,p_city:city
      });
      if(claimed.error)return json(503,'ai_central_zone_claim_unavailable');
      const previous=claimed.data;
      // Una respuesta de localidad, incluso duplicada o sin pedido
      // pendiente, no inicia una segunda cotización por su cuenta.
      handledCentralZoneReply=true;
      const claimState=estadoClaimZonaMvp234(previous);
      if(claimState==='inconsistent')
        return json(503,'ai_central_zone_state_reconciliation_required');
      if(claimState==='resume'){
        if(typeof previous.source_hmac!=='string'||
           typeof previous.source_sha256!=='string'||
           typeof previous.nonce!=='string'||
           typeof previous.ciphertext!=='string'||
           previous.delivery_city!==city)
          return json(503,'ai_central_zone_source_reconciliation_required');
        const modelEnv=Deno.env.get('COTIRONDA_PILOT_AI_CENTRAL_MODEL');
        const model=modelEnv==='gpt-6.1-sol'?'gpt-6.1-sol':'gpt-6-luna';
        const d013ZoneEnabled=habilitarPublicacionD013ConAccesoD016({
          outbound:sec.outbound,
          matchingEnabled:Deno.env.get('COTIRONDA_PILOT_V2_D013_PRODUCT_MATCHING_ENABLED')==='true',
          linkSendEnabled:Deno.env.get('COTIRONDA_PILOT_D016_WHATSAPP_SEND_ENABLED')==='true',
          portalOrigin:Deno.env.get('COTIRONDA_PILOT_D016_PORTAL_ORIGIN')??'',
          portalSha:Deno.env.get('COTIRONDA_PILOT_D016_PORTAL_RELEASE_SHA')??'',
          approvedSha:Deno.env.get('COTIRONDA_PILOT_D016_APPROVED_RELEASE_SHA')??'',
          hmacKeyHex:Deno.env.get('COTIRONDA_PILOT_D016_HMAC_KEY_HEX')??''
        });
        // La localidad continúa siempre por V2. Sólo publicar usa D016.
        const zoneWorker=continuarZonaCentralV2D013;
        const resumed=await zoneWorker({
          autenticadoPorWebhook:true,chatHmac:chatHash,
          sourceHmac:previous.source_hmac,
          originalSha256:previous.source_sha256,
          ciudadConfirmada:city,nonce:previous.nonce,
          ciphertext:previous.ciphertext,
          apiKey:Deno.env.get('COTIRONDA_PILOT_OPENAI_API_KEY')??'',
          model,publicar:d013ZoneEnabled, // D013 solo si acceso privado D016 completo
          decrypt:async(nonce,ciphertext)=>decryptArchivedText(
            sec.aes,nonce,ciphertext,
            chatHash+'|'+previous.source_hmac+'|text'),
          shaText:sha,
          snapshotNonce:previous.snapshot_nonce,
          snapshotCiphertext:previous.snapshot_ciphertext,
          initialCallNo:previous.usage_call_no,
          decryptSnapshot:async(nonce,ciphertext)=>decryptArchivedText(sec.aes,nonce,ciphertext,
            chatHash+'|'+previous.source_hmac+'|'+previous.source_sha256+'|zone-snapshot-v1',200000),
          rpc:async(name,params)=>{
            const r=await db.rpc(name,params);
            return {data:r.data,error:r.error};
          }
        });
        if(resumed.estado==='conciliacion_requerida'||
           resumed.estado==='origen_invalido')
          return json(503,'ai_central_zone_continuation_failed');
        if(resumed.estado==='requiere_revision'){
          aiReply='materials';
          buyerClarificationBody=resumed.pregunta
            ?'Para poder cotizar sin inventar datos, reenviame el pedido completo con la localidad y aclarando: '+resumed.pregunta
            :'Recibí la localidad, pero no pude procesar el pedido. No envié nada a proveedores. Reenviame el pedido completo con la localidad.';
        }
        if(resumed.estado==='ronda_publicada'){
          if(!d013ZoneEnabled||!resumed.requestId)
            return json(503,'buyer_review_bypassed_by_zone_continuation');
          trialDispatchChats.add(chatHash);
          // El evento reciente es la respuesta de localidad autenticada.
          buyerLinkRequests.push({mode:'auto',requestId:resumed.requestId,
           chatHmac:chatHash,eventHmac:messageHash,recipient:row.chat_id});
        }
        if(resumed.estado==='ronda_en_sombra'&&
           !await emitirRevisionUnificada(previous.source_hmac))
          return json(503,'buyer_review_delivery_reconciliation_required');
      }else if(previous?.state==='ambiguous'){
        // Ninguna asignación arbitraria de localidad a pedido.
        handledCentralZoneReply=true;
        aiReply='materials';
        buyerClarificationBody='Tengo más de un pedido pendiente de localidad. Reenviame el pedido completo con su localidad para evitar confusiones.';
      }
    }
  }
  if(centralBuyerText&&!handledCentralZoneReply&&outcome(out.data)==='needs_review'){
    const modelEnv=Deno.env.get('COTIRONDA_PILOT_AI_CENTRAL_MODEL');
    const model=modelEnv==='gpt-6.1-sol'?'gpt-6.1-sol':'gpt-6-luna';
    const d013Enabled=habilitarPublicacionD013ConAccesoD016({
      outbound:sec.outbound,
      matchingEnabled:Deno.env.get('COTIRONDA_PILOT_V2_D013_PRODUCT_MATCHING_ENABLED')==='true',
      linkSendEnabled:Deno.env.get('COTIRONDA_PILOT_D016_WHATSAPP_SEND_ENABLED')==='true',
      portalOrigin:Deno.env.get('COTIRONDA_PILOT_D016_PORTAL_ORIGIN')??'',
      portalSha:Deno.env.get('COTIRONDA_PILOT_D016_PORTAL_RELEASE_SHA')??'',
      approvedSha:Deno.env.get('COTIRONDA_PILOT_D016_APPROVED_RELEASE_SHA')??'',
      hmacKeyHex:Deno.env.get('COTIRONDA_PILOT_D016_HMAC_KEY_HEX')??''
    });
    // Piloto: el intérprete V2 nunca depende del permiso de publicar.
    const buyerWorker=procesarCompradorCentralV2D013;
    const result=await buyerWorker({
      habilitado:true,publicar:d013Enabled, // D013 sin confirmacion; SQL sigue gateado
      autenticadoPorWebhook:true,chatHmac:chatHash,
      messageHmac:messageHash,sourceSha256:textHash,
      fuente:body,apiKey:Deno.env.get('COTIRONDA_PILOT_OPENAI_API_KEY')??'',
      model,
      usageTraceEnabled:true,
      encryptZoneSnapshot:async(value)=>encrypt(sec.aes,value,
       chatHash+'|'+messageHash+'|'+textHash+'|zone-snapshot-v1'),
      rpc:async(name,params)=>{
        const result=await db.rpc(name,params);
        return {data:result.data,error:result.error};
      }
    });
    if(result.estado==='conciliacion_requerida')
      return json(503,'ai_central_reconciliation_required');
    if(result.estado==='requiere_zona')aiReply='zone';
    // V2: una revisión no depende del flujo histórico de confirmaciones.
    // Se conserva el lease autenticado MVP094 (comprador, consentimiento,
    // transporte habilitado, cuota y unicidad por mensaje).
    if(result.estado==='requiere_revision'){
      aiReply='materials';
      buyerClarificationBody=result.pregunta
        ?'Para poder cotizar sin inventar datos, reenviame el pedido completo aclarando: '+result.pregunta
        :'Recibí tu pedido, pero no pude procesarlo en este intento. No envié nada a los proveedores. Podés reenviar el pedido completo con materiales, cantidades y localidad.';
    }
    if(result.estado==='ronda_publicada'){
      if(!d013Enabled||!result.requestId)
        return json(503,'buyer_review_bypassed_by_text_broker');
      trialDispatchChats.add(chatHash);
      buyerLinkRequests.push({mode:'auto',requestId:result.requestId,
       chatHmac:chatHash,eventHmac:messageHash,recipient:row.chat_id});
    }
    if(result.estado==='ronda_en_sombra'&&
       !await emitirRevisionUnificada(messageHash))
      return json(503,'buyer_review_delivery_reconciliation_required');
  }
  // Aclaración breve que cita el PDF ORIGINAL de Cotironda.
  // Un mensaje «Es de este pedido» no debe entrar como cotización.
  const isClarificationAnswer=row.type==='text'&&centralSupplier&&
    respuestaCitaPedidoMvp239(body);
  selectorClarification=isClarificationAnswer&&
    trial.quote_link===true&&supplierQuotedId!==null;
  if(selectorClarification&&
     ['unmatched_quote','needs_review'].includes(outcome(out.data))){
    const settled=await db.rpc('cotironda_piloto_ia_resolve_clarification_mvp239',{
      p_reply_hmac:messageHash,p_chat_hmac:chatHash,
      p_quoted_whapi_id:supplierQuotedId,p_original_text:body
    });
    if(settled.error)return json(503,'ai_supplier_clarification_unavailable');
    const state=settled.data?.state;
    if(!['resolved','ambiguous_source','no_pending_source',
         'quoted_request_not_unique','not_authorized',
         'already_resolved','invitation_after_source',
         'invalid'].includes(state))
      return json(503,'ai_supplier_clarification_state_invalid');
    if(state==='resolved'&&settled.data?.source_kind==='text'&&
       typeof settled.data.source_hmac==='string'&&
       trial.quote_analysis===true){
      const modelEnv=Deno.env.get('COTIRONDA_PILOT_AI_CENTRAL_MODEL');
      const model=modelEnv==='gpt-6.1-sol'?'gpt-6.1-sol':'gpt-6-luna';
      const processed=await procesarPresupuestoCentralMvp227({
       habilitado:true,webhookAutenticado:true,
       commercialMemoryEnabled:Deno.env.get('COTIRONDA_PILOT_COMMERCIAL_MEMORY_ENABLED')==='true',
       quoteVersioningEnabled:Deno.env.get('COTIRONDA_PILOT_QUOTE_VERSIONS_ENABLED')==='true',
       usageTraceEnabled:Deno.env.get('COTIRONDA_PILOT_AI_USAGE_TRACE_ENABLED')==='true',
       messageHmac:settled.data.source_hmac,chatHmac:chatHash,
       apiKey:Deno.env.get('COTIRONDA_PILOT_OPENAI_API_KEY')??'',
       model,
       rpc:async(name,params)=>{
        const reply=await db.rpc(name,params);
        return {data:reply.data,error:reply.error};
       },
       decrypt:async(nonce,ciphertext)=>decryptArchivedText(
        sec.aes,nonce,ciphertext,
        chatHash+'|'+settled.data.source_hmac+'|text'),
       shaText:sha
      });
      if(processed.estado==='conciliacion_requerida')
        return json(503,'ai_supplier_clarification_review_required');
    }
  }
  if(outcome(out.data)==='quote_recorded')supplierAckMode='text_quote';
  // A supplier can have several open invitations. A quoted PDF ID is
  // checked against the exact accepted Whapi outbox for this same seller.
  // V2-02: el codigo NO concede permisos; SQL corrobora Whapi, remitente y SHA.
  if(row.type==='text'&&centralSupplier&&!supplierQuotedId&&
     Deno.env.get('COTIRONDA_PILOT_V2_REFERENCE_LINK_ENABLED')==='true'&&
     ['unmatched_quote','needs_review'].includes(outcome(out.data))&&
     contieneReferenciaPedidoV2(body)){
    const lookup=await db.rpc('cotironda_piloto_v2_quoted_id_for_reference',{
      p_message_hmac:messageHash,p_chat_hmac:chatHash,p_original_text:body
    });
    if(lookup.error)return json(503,'supplier_reference_lookup_unavailable');
    const q=lookup.data?.quoted_whapi_id;
    if(lookup.data?.state==='matched'&&
       typeof q==='string'&&/^[A-Za-z0-9._:-]{8,160}$/u.test(q))
      supplierQuotedId=q;
  }
  let legacySupplierQuoteLinked=false;
  if(row.type==='text'&&supplierQuotedId&&!attachmentNotice&&
     !isClarificationAnswer&&
     outcome(out.data)==='unmatched_quote'){
    const binding=await db.rpc('cotironda_piloto_link_quoted_text_mvp151',{
      p_message_hmac:messageHash,p_chat_hmac:chatHash,
      p_quoted_id:supplierQuotedId,p_plaintext:body
    });
    if(binding.error)return json(503,'supplier_quote_context_unavailable');
    if(binding.data?.state==='linked'){
      supplierAckMode='text_quote';
      legacySupplierQuoteLinked=true;
    }
  }
  // Nueva asociación IA Central: solo texto FUENTE a ronda exacta.
  // No publica precios ni asigna ganadores; bandera OFF por defecto.
  // Un proveedor puede escribir «cemento 8500 por bolsa» sin signo $.
  // El receptor heredado lo deja needs_review: IA Central debe poder
  // asociarlo a la ronda EXACTA igual que los presupuestos formales.
  if(row.type==='text'&&centralSupplier&&!isClarificationAnswer&&
     ['unmatched_quote','needs_review'].includes(outcome(out.data))&&
     !legacySupplierQuoteLinked&&
