  if(field==='payment')answers.push(safe(c.payment)?'Forma de pago solicitada: '+safe(c.payment)+'.':'La forma de pago no quedó registrada para este pedido. Indicá tu condición en el presupuesto.');
  if(field==='vat')answers.push(safe(c.vat)?'IVA solicitado: '+safe(c.vat)+'.':'El IVA no quedó registrado para este pedido. Aclará si tus precios lo incluyen.');
