import {interpretarIntencionTextoProveedorV2,responderConsultaProveedorV2,resumenPrivadoMvp245,type CampoConsultaProveedorV2} from './ai-central-supplier-mvp227.ts';
import {interpretarPresupuestoConIAMvp225} from '../../../src/domain/ia-central/lector-presupuesto-proveedor-mvp225.ts';
import {RUBROS_MVP216,type RubroMvp216} from '../../../src/domain/rubros-comprador-mvp216.ts';
type Rpc=(name:string,params:Record<string,unknown>)=>Promise<{data:unknown;error:unknown}>;
type Io={rpc:Rpc;apiKey:string;model:'gpt-6-luna'|'gpt-6.1-sol';decrypt:(nonce:string,ciphertext:string,aad:string)=>Promise<string>;sha:(text:string)=>Promise<string>;send:(event:string,reply:string)=>Promise<void>;classify?:typeof interpretarIntencionTextoProveedorV2;readQuote?:typeof interpretarPresupuestoConIAMvp225};
const HASH=/^[a-f0-9]{64}$/u;
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;
export async function procesarConversacionProveedorV2(chat:string,id:string,io:Io):Promise<string>{
 if(!HASH.test(chat)||!UUID.test(id))return 'invalid';
 const call=async(name:string,params:Record<string,unknown>)=>{
  const r=await io.rpc(name,params);
  if(r.error||!r.data||typeof r.data!=='object'||Array.isArray(r.data))throw Error('supplier_conversation_rpc');
  return r.data as Record<string,unknown>;
 };
 const g=await call('cotironda_piloto_v2_supplier_conversation_claim',{p_chat_hmac:chat,p_id:id});
 if(g.state!=='claimed')return String(g.state);
 if(g.conversation_id!==id||typeof g.revision!=='number'||!Number.isSafeInteger(g.revision)||typeof g.lease!=='string'||!UUID.test(g.lease)||!Array.isArray(g.sources)||!g.sources.length)return 'claim_invalid';
 const fields={p_chat_hmac:chat,p_id:id,p_revision:g.revision,p_lease:g.lease};
 const review=async()=>String((await call('cotironda_piloto_v2_supplier_conversation_review',fields)).state);
 let context;
 try{context=await abrirConversacionTextoV2({chatHmac:chat,fuentes:g.sources as FuenteConversacionV2[],descifrar:io.decrypt,sha256:io.sha})}catch{return review()}
 if(context.texto.length>4000)return review();
 let questionFields:CampoConsultaProveedorV2[]=[];
 const intent=await (io.classify??interpretarIntencionTextoProveedorV2)({source:context.texto,apiKey:io.apiKey,model:io.model,hasQuotedRequest:typeof g.reference==='string',onQuestion:f=>{questionFields=f}});
 // Cotizaciones agrupadas: ninguna fuente sintética, lectura y asociación sobre originales.
 if(intent==='quote'){
  const fragments=context.tramos.map(t=>({message_hmac:t.messageHmac,text:context.texto.slice(t.inicio,t.fin)}));
  const scope=await call('cotironda_piloto_v2_supplier_group_quote_context',{...fields,p_fragments:fragments});
  if(scope.state!=='context')return scope.state==='stale'?'stale':review();
  if(typeof scope.request_id!=='string'||!UUID.test(scope.request_id)||typeof scope.context_sha256!=='string'||!HASH.test(scope.context_sha256)||scope.context_sha256!==await io.sha(context.texto)||!Array.isArray(scope.items)||scope.items.length<1||scope.items.length>25)return review();
  const requested=[];
  for(const item of scope.items){
   if(!item||typeof item!=='object'||typeof item.id!=='string'||!/^item_[1-9][0-9]{0,2}$/u.test(item.id)||typeof item.descripcion!=='string'||item.descripcion.length<3||item.descripcion.length>500||typeof item.cantidad!=='string'||item.cantidad.length>40||typeof item.unidad!=='string'||item.unidad.length>20||typeof item.rubro!=='string'||!Object.hasOwn(RUBROS_MVP216,item.rubro))return review();
   requested.push({id:item.id,descripcion:item.descripcion,cantidad:item.cantidad,unidad:item.unidad,rubro:item.rubro as RubroMvp216});
  }
  const reading=await (io.readQuote??interpretarPresupuestoConIAMvp225)({fuente:context.texto,pedido:requested,etiquetaAnonima:'Presupuesto privado',apiKey:io.apiKey,model:io.model});
  if(reading.estado!=='interpretada_para_revision'||!reading.oferta||!reading.cobertura||reading.cobertura.ofertas.length!==1)return review();
  const summary=resumenPrivadoMvp245(reading);if(!summary)return review();
  // La suma de presentación no es una comparación ni un total declarado.
  // Solo precios conciliados para TODOS los materiales ofertados; ningún
  // adicional, descuento, cargo o precio sin representar puede quedar afuera.
  const evaluated=reading.cobertura.ofertas[0],offer=reading.oferta;
  const materials=offer.lineas.filter(l=>l.tipo==='material');
  const priced=new Set(evaluated.precios.map(p=>p.numeroOferta));
  summary.group_sum_eligible=materials.length>0&&materials.length===priced.size&&
   evaluated.precios.length===priced.size&&materials.every(l=>priced.has(l.numero))&&
   evaluated.motivos.every(m=>m==='moneda_no_informada')&&
   offer.lineas.every(l=>l.tipo==='material'||(l.tipo==='aclaracion'&&
    l.precioUnitarioLiteral===null&&l.totalLineaLiteral===null&&
    !/\d|\$|descuento|bonificaci[oó]n|recargo|flete|iva/iu.test(l.textoOriginal)))&&
   !/\b(?:descuento|bonificaci[oó]n|recargo|flete\s+(?:aparte|a\s+convenir)|m[aá]s\s+iva|\+\s*iva)\b/iu.test(context.texto);

  const verified=reading.cobertura.ofertas[0].estado==='verificada_para_comparacion'&&['ARS','USD'].includes(String(summary.moneda));
  const saved=await call('cotironda_piloto_v2_supplier_group_quote_finish',{...fields,p_fragments:fragments,p_request_id:scope.request_id,p_context_sha256:scope.context_sha256,p_state:verified?'verified':'review',p_reason:verified?'source_and_math_checked':'conditions_need_review',p_summary:summary,p_fields:questionFields});
  if(saved.state!=='saved_private')return saved.state==='stale'?'stale':review();
  const reply=responderConsultaProveedorV2(saved.reply);
  if(reply&&typeof saved.message_hmac==='string'&&HASH.test(saved.message_hmac))await io.send(saved.message_hmac,reply);
  return String(saved.state);
 }
 // An attachment notice or an ambiguous group remains private.
 if(intent!=='non_quote')return review();
 const result=await call('cotironda_piloto_v2_supplier_conversation_finish_question',{...fields,p_fields:questionFields});
 if(result.state==='reply_reserved'){
  const reply=responderConsultaProveedorV2(result);
  if(typeof result.message_hmac!=='string'||!HASH.test(result.message_hmac)||!reply)return 'reply_reconciliation_required';
  await io.send(result.message_hmac,reply);
 }
 return String(result.state);
}

/** Extract entire supported document from the original private bytes.
 * No second semantic reader, no city requirement inside a file.
 * Never treat scanned PDF, an image or an unsupported layout as text. */
import {readOfficeVisibleRows} from './supplier-source-office.ts';
import {readPdfPositioned} from './supplier-source-pdf-general.ts';
const HEX=/^[a-f0-9]{64}$/u;
const PDF='application/pdf';
const DOCX='application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const XLSX='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
const CTRL=/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u;
export async function leerAdjuntoConversacionV2(args:{
 manifest:string;authorized:unknown;bytes:Uint8Array;sha:(s:string)=>Promise<string>;
 pdf?:typeof readPdfPositioned;office?:typeof readOfficeVisibleRows;
}):Promise<{texto:string;mediaSha256:string;derivedSha256:string}>{
 const m=JSON.parse(args.manifest),a=args.authorized;
 if(!a||typeof a!=='object'||Array.isArray(a))throw Error('attachment_scope');
 const scope=a as Record<string,unknown>;
 if(scope.state!=='authorized_document'||typeof scope.sha256!=='string'||!HEX.test(scope.sha256)||
    typeof scope.mime!=='string'||typeof scope.size!=='number'||scope.size!==args.bytes.length||
    args.bytes.length<1||args.bytes.length>3145728||
    m?.version!==1||m.origin!=='whapi'||m.kind!=='document'||m.state!=='awaiting_secure_download'||
    m.mime!==scope.mime||typeof m.media_id!=='string'||await args.sha(m.media_id)!==scope.manifest_id_sha256||
    (m.size!==null&&m.size!==scope.size))throw Error('attachment_scope');
 const actual=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',Uint8Array.from(args.bytes))),b=>b.toString(16).padStart(2,'0')).join('');
 if(actual!==scope.sha256)throw Error('attachment_bytes_changed');
 let rows:string[];
 if(scope.mime===PDF){
  const result=await (args.pdf??readPdfPositioned)(args.bytes);
  if(result.scanned||result.pages<1||result.pages>12||result.rows.some(r=>!Number.isInteger(r.page)||r.page<1||r.page>result.pages))throw Error('attachment_pdf_layout');
  rows=result.rows.map(r=>r.text);
 }else if(scope.mime===DOCX||scope.mime===XLSX){
  rows=[...await (args.office??readOfficeVisibleRows)({bytes:args.bytes,mime:scope.mime,sha256:actual})];
 }else if(scope.mime==='text/plain'||scope.mime==='text/csv'){
  rows=new TextDecoder('utf-8',{fatal:true}).decode(args.bytes).split(/\r?\n/u).filter(r=>r.trim());
 }else throw Error('attachment_format');
 if(rows.length<1||rows.length>90||rows.some(r=>typeof r!=='string'||!r.trim()||r.length>800||CTRL.test(r)))throw Error('attachment_rows');
 const caption=m.caption;
 if(caption!==null&&(typeof caption!=='string'||caption.length>500||CTRL.test(caption)))throw Error('attachment_caption');
 const texto=(caption?caption+'\n\n':'')+rows.join('\n');
 if(texto.length<3||texto.length>12000)throw Error('attachment_length');
 return {texto,mediaSha256:actual,derivedSha256:await args.sha(texto)};
}
